INSERT INTO question_seed
COPY t FROM STDIN;
1	привет
3	\N
___
```', '{"A":"`\\N`","B":"`\\q`","C":"`;`","D":"`\\.`"}'::jsonb, 'D', 'COPY FROM добавляет строки к тем, что уже есть в таблице, поэтому в демонстрации курса перед загрузкой таблицу очистили командой TRUNCATE.', '{"A":"Так в текстовом формате COPY записывается NULL, а не конец данных: в опыте сервер сообщил, что нет данных для столбца s.","B":"Внутри ввода COPY это обычная строка данных: в опыте сервер попытался прочитать её как значение n и выдал ошибку.","C":"Точка с запятой завершает команду SQL, а в потоке данных это обычный символ: в опыте сервер принял её за значение n.","D":"Обратная косая черта с точкой в отдельной строке завершает ввод, как в демонстрации курса. Конец ввода (Ctrl+D) тоже завершает его."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'В базе bk2 уже есть таблица t с тремя строками. Выполняют pg_dump -t t bk | psql -d bk2, в t базы bk четыре строки, ON_ERROR_STOP не задан. Что верно?', '{"A":"t пересоздастся, в ней будет четыре строки","B":"psql прервёт скрипт на первой же ошибке","C":"CREATE TABLE завершится ошибкой: t уже есть","D":"COPY добавит четыре строки к трём имеющимся"}'::jsonb, 'CD', 'Копия pg_dump создаёт объекты и добавляет данные, а не заменяет их, поэтому перед загрузкой проверяют, что уже лежит в базе. Запуск psql -v ON_ERROR_STOP=1 остановит скрипт на первой ошибке.', '{"A":"Команд DROP в такой копии нет, их добавляет ключ --clean при выгрузке.","B":"Без ON_ERROR_STOP psql сообщает об ошибке и выполняет следующие команды.","C":"В опыте psql сообщил «отношение \"t\" уже существует» и продолжил выполнять скрипт.","D":"COPY FROM добавляет строки и таблицу не очищает: в опыте в t стало 7 строк."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Обычная роль alice (не суперпользователь, ни в какие роли не входит) с правом SELECT на t выполняет COPY t TO ''/tmp/t.csv'' WITH (FORMAT csv). Что получится?', '{"A":"Файл /tmp/t.csv появится на машине alice","B":"Ошибка: писать в файлы сервера ей нельзя","C":"Файл появится на сервере от имени ОС postgres","D":"Ошибка: COPY TO не поддерживает формат csv"}'::jsonb, 'B', 'Обычной роли подходит COPY t TO STDOUT или метакоманда psql \copy t TO ''t.csv'' WITH (FORMAT csv): данные идут по сети, а файл пишется на клиенте от имени пользователя ОС, запустившего psql. В опыте \copy у alice сработал.', '{"A":"Имя файла в команде SQL COPY относится к серверу. На клиенте файл пишет метакоманда \\copy.","B":"COPY в файл разрешён суперпользователю и членам pg_write_server_files: в опыте «нет прав для выполнения COPY с записью в файл».","C":"Так было бы у суперпользователя: файл пишет процесс сервера от имени пользователя ОС postgres.","D":"Формат csv для COPY TO допустим, дело в правах на файлы сервера."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Копию сняли командой pg_dump --create appdb > appdb.sql. На том же сервере, где appdb продолжает работать, создали пустую базу appdb_test и выполнили psql -d appdb_test -f appdb.sql. Что произойдёт?', '{"A":"CREATE DATABASE appdb завершится ошибкой","B":"psql откажется выполнять скрипт в другой базе","C":"Скрипт подключится к appdb и выполнит команды там","D":"Объекты и данные загрузятся в базу appdb_test"}'::jsonb, 'AC', 'Чтобы восстановить копию под другим именем, её выгружают без --create, создают базу из template0 и выполняют скрипт в ней. Копию с --create выполняют, подключившись к другой базе, например postgres, когда исходной базы на сервере нет.', '{"A":"Скрипт начинается с CREATE DATABASE appdb WITH TEMPLATE = template0, а такая база уже есть.","B":"psql такой проверки не делает и выполняет команды скрипта по порядку.","C":"После CREATE DATABASE в скрипте стоит \\connect appdb: в опыте объекты и данные пошли в существующую базу.","D":"База из -d нужна для первого подключения, дальше скрипт сам подключается к appdb. В опыте appdb_test осталась пустой."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Копию базы appdb сняли командой pg_dump -Fc -f appdb.dump appdb. Утром кто-то удалил таблицу orders, остальные данные с тех пор менялись, их трогать нельзя. Как вернуть orders?', '{"A":"psql -d appdb -t orders -f appdb.dump","B":"pg_dump -d appdb -t orders -f orders.sql","C":"pg_restore -d appdb --clean appdb.dump","D":"pg_restore -d appdb -t orders appdb.dump"}'::jsonb, 'D', 'Выбирать объекты при восстановлении позволяет оглавление копии в специальном формате и в формате directory, его показывает pg_restore -l. Индексы и ограничения таблицы ключ -t у pg_restore не восстанавливает, их выбирают отдельно. Из копии в виде SQL-скрипта одну таблицу так не достать.', '{"A":"psql не читает специальный формат: в опыте он ответил, что такую копию восстанавливают pg_restore. Ключ -t у psql означает вывод без заголовков.","B":"Это новая выгрузка из рабочей базы, где orders уже нет, а не восстановление из копии.","C":"Так восстановится вся база: остальные таблицы вернутся к состоянию на момент копии.","D":"pg_restore выбирает объекты по оглавлению копии: в опыте вернулась удалённая таблица с данными, другие таблицы не изменились."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Нужна логическая копия кластера вместе с ролями и табличными пространствами. Базы большие, выгружать и восстанавливать их хочется в несколько процессов. Что выбрать?', '{"A":"pg_dumpall > all.sql и затем pg_restore -j 4 all.sql","B":"pg_dumpall -Fd -j 4 по всему кластеру за один запуск","C":"pg_dumpall --globals-only и pg_dump -Fd -j по каждой базе","D":"pg_dump -Fd -j 4 по каждой базе, роли войдут в копии"}'::jsonb, 'C', 'pg_dump выгружает в несколько процессов только в формате directory: в опыте с -j и обычным форматом он отказался. pg_restore восстанавливает в несколько процессов копии в форматах custom и directory.', '{"A":"pg_restore не читает SQL-скрипт: в опыте он ответил, что файл текстовый и загружать его нужно psql.","B":"pg_dumpall выдаёт только SQL-скрипт для psql: ключей формата и параллельности у него нет, в опыте -F был отвергнут.","C":"Роли и табличные пространства выгружает pg_dumpall -g, а pg_dump в формате directory выгружает базу в несколько процессов. Восстанавливают её pg_restore -j.","D":"pg_dump не выгружает роли и табличные пространства: это объекты всего кластера."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Сервер упал при сбое питания. Пока он выключен, каталог данных целиком, вместе с pg_wal, скопировали cp -a на сервер с той же версией и архитектурой и запустили копию. Что будет?', '{"A":"Накат по WAL от последней контрольной точки","B":"Отказ запуска: сервер был выключен неаккуратно","C":"Запуск без наката: данные на диске уже согласованы","D":"Запуск, но сначала нужно создать recovery.signal"}'::jsonb, 'A', 'Холодную копию аккуратно остановленного сервера запускают сразу, журналы ей не нужны. Копия после сбоя тоже годится, если в ней есть pg_wal от последней контрольной точки: сервер накатит записи и придёт к согласованному состоянию.', '{"A":"Это обычное восстановление после сбоя: в опыте копия сообщила «система БД была остановлена нештатно; производится автоматическое восстановление» и приняла подключения.","B":"Копия содержит pg_wal, а журнал и нужен, чтобы довести такие данные до согласованного состояния.","C":"Так было бы после аккуратной остановки, когда контрольная точка сбросила грязные страницы. После сбоя часть изменений есть только в WAL.","D":"recovery.signal нужен для восстановления из архива. Восстановление после сбоя сервер выполняет сам."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'В каталоге /backup/base лежат файлы вчерашней копии. Выполняют pg_basebackup -D /backup/base. Что получится?', '{"A":"Ошибка: каталог существует и он не пуст","B":"Старые файлы заменятся файлами новой копии","C":"Скопируются файлы, изменённые со вчерашнего дня","D":"Новая копия ляжет в подкаталог с текущей датой"}'::jsonb, 'A', 'В демонстрации курса перед копированием каталог удалили командой rm -rf. На практике каждую копию кладут в новый каталог, например с датой в имени, а старые удаляют по своему расписанию.', '{"A":"pg_basebackup пишет в пустой или несуществующий каталог: в опыте «каталог ... существует, но он не пуст». Это защита от случайной перезаписи прошлой копии.","B":"Перезаписывать прошлую копию утилита не станет: каталог нужно очистить или указать другой.","C":"pg_basebackup в PostgreSQL 16 копирует кластер целиком. Инкрементные копии появились в версии 17 и задаются отдельным ключом.","D":"Подкаталогов pg_basebackup сам не создаёт: копия ложится прямо в каталог из -D."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'pg_basebackup на нагруженном сервере долго ждёт контрольную точку перед копированием. Допишите значение, чтобы она выполнилась сразу:
```
pg_basebackup -D /backup/base --checkpoint=___
```', '{"A":"`immediate`","B":"`spread`","C":"`force`","D":"`fast`"}'::jsonb, 'D', 'Короткая форма ключа: -c fast. При log_checkpoints = on контрольная точка по умолчанию видна в журнале как force wait, а с fast — как immediate force wait.', '{"A":"Такого значения нет: в опыте pg_basebackup ответил, что допустимы fast и spread. Слово immediate пишется в журнал у контрольной точки, запрошенной с fast.","B":"Это значение по умолчанию: запись грязных страниц растягивается на долю checkpoint_completion_target от интервала контрольных точек, при настройках по умолчанию до 4,5 минуты.","C":"Такого значения нет: допустимы fast и spread.","D":"Быстрая контрольная точка: грязные страницы сбрасываются сразу, ценой всплеска записи на диск. В демонстрации курса использовали именно её."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Автономную копию развернули в /var/lib/postgresql/16/replica, владелец каталога — пользователь ОС postgres. С какими правами на этот каталог сервер запустится?', '{"A":"0750: владельцу всё, группе чтение и вход","B":"0700: владельцу всё, остальным ничего","C":"0755: владельцу всё, всем чтение и вход","D":"0770: владельцу и группе полный доступ"}'::jsonb, 'AB', 'Кроме прав сервер проверяет владельца: каталог должен принадлежать пользователю ОС, от имени которого запускается сервер. В демонстрации курса после mv каталог передали postgres командой chown.', '{"A":"Допустимо: группе разрешено только чтение, например чтобы копию снимал другой пользователь ОС. В опыте сервер запустился.","B":"Эти права ставят initdb и pg_basebackup: в опыте у копии каталоги были 0700, файлы 0600.","C":"В опыте сервер не запустился: «установлены неправильные права доступа», маска должна быть 0700 или 0750.","D":"Запись для группы тоже запрещена: в опыте та же ошибка."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'В pg_hba.conf одна строка: local all all trust. Суперпользователь postgres через сокет входит в psql без вопросов, но pg_basebackup с тем же пользователем получает отказ. Почему?', '{"A":"all в поле базы не охватывает репликацию","B":"Метод trust запрещён для репликации","C":"У роли postgres нет атрибута REPLICATION","D":"pg_basebackup не подключается через сокет"}'::jsonb, 'A', 'Физическая копия снимается со всего кластера, поэтому подключение по протоколу репликации не относится к конкретной базе, и в pg_hba.conf его выделяет слово replication. Роли нужен ещё атрибут REPLICATION, если она не суперпользователь.', '{"A":"Подключению по протоколу репликации нужна строка со словом replication в поле базы: в опыте «в pg_hba.conf нет записи, разрешающей подключение для репликации».","B":"trust допустим и для репликации: в опыте со строкой local replication all trust pg_basebackup подключился.","C":"Суперпользователю атрибут REPLICATION не нужен, отказ дал файл pg_hba.conf.","D":"Подключается: в демонстрации курса копию сняли через локальный сокет по строке local replication all trust."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'archive_mode = on, archive_command = ''cp %p /mnt/archive/%f || true''. Ночью отвалился сетевой диск /mnt/archive. Что будет с заполненными сегментами WAL?', '{"A":"Сервер остановится с ошибкой архивации","B":"Сервер сочтёт их сохранёнными и со временем удалит","C":"Они останутся в pg_wal до успешного копирования","D":"Архивация приостановится до перезапуска сервера"}'::jsonb, 'B', 'Сервер верит коду возврата: 0 означает «сегмент сохранён». Команда должна возвращать 0, только когда копия действительно записана, иначе в архиве появятся пропуски и восстановление по нему остановится на первом из них.', '{"A":"Из-за архивации сервер не останавливается: при честной ошибке он повторяет попытки.","B":"Из-за || true команда всегда возвращает 0: в опыте pg_stat_archiver показал archived_count = 1 и failed_count = 0, а в архив ничего не попало.","C":"Так было бы при ненулевом коде возврата, но || true его скрывает.","D":"Сервер не отключает архивацию сам и вызывает команду для каждого сегмента."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Каталог /archive пуст. В pg_wal сервера лежат сегменты 000000010000000000000002 и …03, сейчас сервер пишет в …03. Запускают pg_receivewal -D /archive. С чего начнётся архив?', '{"A":"С текущей позиции записи в …03","B":"С начала текущего сегмента …03","C":"С самого старого сегмента …02","D":"С последней контрольной точки"}'::jsonb, 'B', 'Если в каталоге уже есть сегменты, утилита продолжает с начала сегмента, следующего за последним заполненным. Поэтому базовую копию для такого архива снимают после запуска pg_receivewal: более ранние сегменты в него не попадут.', '{"A":"Начало берётся с границы сегмента, чтобы файл в архиве был полным сегментом.","B":"Если каталог пуст, утилита запрашивает записи с начала текущего сегмента сервера: в опыте первым появился 000000010000000000000003.partial.","C":"Прошлые сегменты утилита не выкачивает: в опыте сегмент …02 в архив не попал.","D":"Контрольные точки на выбор стартовой позиции не влияют."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Архив ведёт pg_receivewal. Базовую копию сняли раньше, сегменты после неё до …04 в архиве заполнены, последний — 000000010000000000000005.partial. Копию восстанавливают с recovery.signal и restore_command = ''cp /archive/%f %p''. Что будет с изменениями из …05?', '{"A":"Сервер не запустится, пока не найдёт …05","B":"Подтянутся из pg_wal основного сервера","C":"Применятся: restore_command возьмёт .partial","D":"Потеряются, если не переименовать .partial"}'::jsonb, 'D', 'Последний недописанный файл копируют под именем сегмента, например в pg_wal восстанавливаемого сервера: в опыте после этого восстановились и база, и таблица. Это совет к практике+ курса.', '{"A":"Согласованность уже достигнута на …04, поэтому сервер завершает восстановление на последней найденной записи и переходит в обычный режим.","B":"restore_command берёт файлы из указанного места, к основному серверу восстановление из архива не подключается.","C":"Команда копирует файл с именем %f, а имя файла .partial с ним не совпадает.","D":"restore_command ищет файл по имени сегмента без суффикса: в опыте восстановление закончилось на …04, а созданной позже базы не оказалось."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'При работающем pg_receivewal сняли копию pg_basebackup -X none, развернули её и запустили сервер, забыв recovery.signal и restore_command. Что получится?', '{"A":"Запуск на момент окончания базового копирования","B":"Запуск в режиме реплики, без права записи","C":"Отказ: не найдена запись контрольной точки","D":"Сервер сам прочитает нужные сегменты из архива"}'::jsonb, 'C', 'При выключенной файловой архивации pg_basebackup -X none предупреждает, что сегменты WAL нужно обеспечить другими средствами. Для запуска такой копии создают recovery.signal и задают restore_command, как в практике+ курса.', '{"A":"Для этого нужны сегменты WAL за время копирования, а с -X none их в копии нет.","B":"Режим реплики включает файл standby.signal.","C":"В копии нет сегментов WAL, а без recovery.signal сервер в архив не идёт: в опыте «не удалось найти нужную запись контрольной точки» и подсказка создать recovery.signal.","D":"Где архив, сервер узнаёт из restore_command, а читать его начинает при recovery.signal."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Сервер восстановили из базовой копии и архива WAL с recovery.signal, без целевой точки. Он применил все сегменты архива и перешёл в обычный режим. Что верно?', '{"A":"recovery.signal остаётся до ручного удаления","B":"В pg_wal появился файл 00000002.history","C":"Новые сегменты пишутся с префиксом 00000001","D":"Сервер перешёл на новую линию времени 2"}'::jsonb, 'BD', 'Без целевой точки сервер применяет все доступные записи WAL. Линия времени отделяет историю восстановленного сервера от истории старого: сегменты разных линий не путаются, даже если оба сервера пишут в один архив.', '{"A":"После окончания восстановления сервер удаляет recovery.signal: в опыте файла в каталоге не осталось.","B":"Файл истории описывает, в какой точке линия 2 ответвилась от линии 1. При включённой архивации он тоже уходит в архив.","C":"Тогда их имена совпали бы с сегментами старого сервера в общем архиве, а новая линия времени этого не допускает.","D":"В опыте журнал: «выбранный ID новой линии времени: 2», имена новых сегментов начались с 00000002."}'::jsonb;

DO $check$
DECLARE candidate record; matches integer;
BEGIN
    FOR candidate IN SELECT * FROM question_seed LOOP
        SELECT count(*) INTO matches FROM questions q
        WHERE regexp_replace(trim(q.question_text), '[[:space:]]+', ' ', 'g') =
              regexp_replace(trim(candidate.question_text), '[[:space:]]+', ' ', 'g');
        IF matches > 1 OR (matches = 1 AND NOT EXISTS (
            SELECT 1 FROM questions q WHERE q.question_text = candidate.question_text
              AND q.category_id = candidate.category_id AND q.options = candidate.options
              AND q.correct_answer = candidate.correct_answer AND q.explanation = candidate.explanation
              AND q.option_notes = candidate.option_notes
        )) THEN
            RAISE EXCEPTION 'Конфликт содержимого или повтор нового вопроса';
        END IF;
    END LOOP;
END
$check$;

INSERT INTO questions(category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM question_seed n
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
BEGIN
    IF (SELECT count(*) FROM questions q JOIN question_seed n ON q.question_text = n.question_text) <> 17 THEN
        RAISE EXCEPTION 'Неверное число вопросов после добавления';
    END IF;
END
$check$;

COMMIT;
