BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE question_seed (
    category_id integer NOT NULL,
    question_text text NOT NULL UNIQUE,
    options jsonb NOT NULL,
    correct_answer text NOT NULL,
    explanation text NOT NULL,
    option_notes jsonb NOT NULL
) ON COMMIT DROP;

SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'Таблица t (n numeric, s text) содержит строки (2, '''') и (3, NULL), в выводе SELECT в psql они выглядят одинаково. Что покажет для них COPY t TO STDOUT в текстовом формате по умолчанию?', '{"A":"Обе строки с пустым вторым полем","B":"Строку 2 с \\N, строку 3 с пустым полем","C":"Строку 2 с пустым полем, строку 3 с \\N","D":"Строку 2 с \"\", строку 3 с пустым полем"}'::jsonb, 'C', 'Обозначение NULL в COPY задаёт параметр NULL. Изображение NULL в результатах запросов psql задаёт \pset null: в демонстрации курса после \pset null ''<>'' строка 3 стала отличаться от строки 2.', '{"A":"Тогда при загрузке нельзя было бы отличить пустую строку от NULL, а COPY их различает.","B":"Наоборот: \\N обозначает NULL, а пустая строка выводится пустым полем.","C":"В текстовом формате NULL записывается как \\N, а пустая строка — пустым полем: в опыте вышло «2», табуляция, ничего и «3», табуляция, \\N.","D":"Так выглядит формат csv: там NULL — пустое поле без кавычек, а пустая строка — две кавычки."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '14.'), 'В psql выполнили COPY t FROM STDIN и ввели строки данных. Допишите строку, которой завершают ввод:
```
